package io.invenlio.fulfillment;import jakarta.servlet.http.HttpServletRequest;import java.net.URI;import java.util.Set;import org.slf4j.MDC;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice class FulfillmentExceptionHandler{@ExceptionHandler(FulfillmentException.class)ResponseEntity<ProblemDetail>handle(FulfillmentException e,HttpServletRequest r){HttpStatus s=e.code().endsWith("NOT_FOUND")?HttpStatus.NOT_FOUND:Set.of("CONCURRENT_MODIFICATION","PICK_TASK_ALREADY_COMPLETED","PACKAGE_ITEM_EXCEEDS_PICKED_QUANTITY","SERIAL_ALREADY_PACKED","FULFILLMENT_ALREADY_STARTED","PACKING_SESSION_INCOMPLETE","PICK_ALLOCATION_RECONCILIATION_FAILED","PACKAGE_ALREADY_SHIPPED","SHIPMENT_ALREADY_DISPATCHED","SHIPMENT_IDEMPOTENCY_KEY_REUSED","SHIPMENT_INVENTORY_NOT_AVAILABLE","INVALID_SHIPMENT_TRANSITION","SHIPMENT_NOT_EDITABLE").contains(e.code())?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;var p=ProblemDetail.forStatusAndDetail(s,e.getMessage());p.setType(URI.create("https://invenlio.io/problems/"+e.code().toLowerCase().replace('_','-')));p.setTitle(s.getReasonPhrase());p.setInstance(URI.create(r.getRequestURI()));p.setProperty("code",e.code());p.setProperty("correlationId",MDC.get("correlationId"));return ResponseEntity.status(s).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);}}
